SELECT issue_no AS issueNo, payment_order_id AS paymentOrderId, order_no AS orderNo, customer_name AS customerName, payment_method AS paymentMethod, channel_code AS channelCode, issue_type AS issueType, issue_type_tag AS issueTypeTag, severity, severity_type AS severityType, payment_status AS paymentStatus, payment_status_type AS paymentStatusType, issue_summary AS issueSummary, root_cause_hint AS rootCauseHint, recommended_action AS recommendedAction, recommended_route AS recommendedRoute, COALESCE(latest_action.handling_status, '待分派') AS handlingStatus, COALESCE(latest_action.handling_status_type, 'warn') AS handlingStatusType, COALESCE(latest_action.assignee, '未分派') AS assignee, CASE WHEN payment_issue_union.severity = 'P1' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 30 THEN '已超时' WHEN payment_issue_union.severity = 'P2' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 120 THEN '已超时' ELSE 'SLA内' END AS slaStatus, CASE WHEN payment_issue_union.severity = 'P1' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 30 THEN 'danger' WHEN payment_issue_union.severity = 'P2' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 120 THEN 'danger' ELSE 'success' END AS slaStatusType, CASE WHEN payment_issue_union.severity = 'P1' THEN CONCAT('P1 SLA 30分钟，已耗时', TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()), '分钟') ELSE CONCAT('P2 SLA 120分钟，已耗时', TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()), '分钟') END AS slaTimeLeft, CASE WHEN payment_issue_union.severity = 'P1' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 30 THEN '升级值班负责人' WHEN payment_issue_union.severity = 'P2' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 120 THEN '升级支付运营负责人' ELSE '当班跟进' END AS escalationStatus, CASE WHEN payment_issue_union.severity = 'P1' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 30 THEN 'danger' WHEN payment_issue_union.severity = 'P2' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 120 THEN 'danger' ELSE 'info' END AS escalationStatusType, CASE WHEN payment_issue_union.severity = 'P1' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 30 THEN '立即同步支付后端、渠道值班和运营负责人' WHEN payment_issue_union.severity = 'P2' AND TIMESTAMPDIFF(MINUTE, STR_TO_DATE(payment_issue_union.created_at, '%Y-%m-%d %H:%i:%s'), NOW()) >= 120 THEN '同步支付运营负责人并确认补偿结果' ELSE '由当前处理人按建议动作继续跟进' END AS escalationSuggestion, COALESCE(CONCAT(latest_action.action_type, '：', latest_action.action_remark), '暂无处理动作') AS latestActionSummary, DATE_FORMAT(latest_action.created_at, '%Y-%m-%d %H:%i:%s') AS latestActionAt, payment_issue_union.created_at AS createdAt FROM (
) payment_issue_union LEFT JOIN t_payment_issue_action_log latest_action ON latest_action.id = ( SELECT action_log.id FROM t_payment_issue_action_log action_log WHERE action_log.issue_no = payment_issue_union.issue_no ORDER BY action_log.created_at DESC, action_log.id DESC LIMIT 1 )
payment_order_id LIKE CONCAT('%', #{query.paymentOrderId}, '%')
AND order_no LIKE CONCAT('%', #{query.orderNo}, '%')
AND issue_type = #{query.issueType}
AND severity = #{query.severity}
AND channel_code LIKE CONCAT('%', #{query.channelCode}, '%')
AND payment_method = #{query.paymentMethod}
ORDER BY payment_issue_union.created_at DESC, issue_no DESC LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(1)
FROM (

) payment_issue_union


        payment_order_id LIKE CONCAT('%', #{query.paymentOrderId}, '%')


